#!/bin/bash
# Generated by train_jobs.py — regenerate instead of editing array ranges.
# train_jobs: resource_profile=medium
# train_jobs: job_indices=6,7,8,9,10,11,21,22,23,24,25,26,36,37,38,39,40,41,51,52,53,54,55,56
#
# SLURM_ARRAY_TASK_ID selects jobs.jsonl index (not feeder/grid id):
#   [6] grid=240 suffix=default  240bus_Master_penalty_pf_rho1e4
#   [7] grid=240 suffix=default  240bus_Master_penalty_pf_rho1e4
#   [8] grid=240 suffix=default  240bus_Master_penalty_pf_rho1e4
#   [9] grid=906 suffix=default  906bus_Master_penalty_pf_rho1e4
#   [10] grid=906 suffix=default  906bus_Master_penalty_pf_rho1e4
#   [11] grid=906 suffix=default  906bus_Master_penalty_pf_rho1e4
#   [21] grid=240 suffix=default  240bus_Master_penalty_pf_rho1e5
#   [22] grid=240 suffix=default  240bus_Master_penalty_pf_rho1e5
#   [23] grid=240 suffix=default  240bus_Master_penalty_pf_rho1e5
#   [24] grid=906 suffix=default  906bus_Master_penalty_pf_rho1e5
#   [25] grid=906 suffix=default  906bus_Master_penalty_pf_rho1e5
#   [26] grid=906 suffix=default  906bus_Master_penalty_pf_rho1e5
#   [36] grid=240 suffix=default  240bus_Master_penalty_pf_rho1e5_no_topo
#   [37] grid=240 suffix=default  240bus_Master_penalty_pf_rho1e5_no_topo
#   [38] grid=240 suffix=default  240bus_Master_penalty_pf_rho1e5_no_topo
#   [39] grid=906 suffix=default  906bus_Master_penalty_pf_rho1e5_no_topo
#   [40] grid=906 suffix=default  906bus_Master_penalty_pf_rho1e5_no_topo
#   [41] grid=906 suffix=default  906bus_Master_penalty_pf_rho1e5_no_topo
#   [51] grid=240 suffix=default  240bus_Master_penalty_pf_rho1e6
#   [52] grid=240 suffix=default  240bus_Master_penalty_pf_rho1e6
#   [53] grid=240 suffix=default  240bus_Master_penalty_pf_rho1e6
#   [54] grid=906 suffix=default  906bus_Master_penalty_pf_rho1e6
#   [55] grid=906 suffix=default  906bus_Master_penalty_pf_rho1e6
#   [56] grid=906 suffix=default  906bus_Master_penalty_pf_rho1e6
# Submit without overriding --array; use train_jobs.py verify after regenerate.
#SBATCH --requeue
#SBATCH --job-name=train_penalty_pf
#SBATCH --output=logs/training/penalty_pf/%A_%a.out
#SBATCH --error=logs/training/penalty_pf/%A_%a.err
#SBATCH --array=6,7,8,9,10,11,21,22,23,24,25,26,36,37,38,39,40,41,51,52,53,54,55,56%20
#SBATCH --time=23:00:00
#SBATCH --cpus-per-task=4
#SBATCH --mem=64G
#SBATCH -G h200:1
#SBATCH --partition=pi_donti_gpu,mit_preemptable

set -euo pipefail

if [ -n "${SLURM_SUBMIT_DIR:-}" ] && [ -f "$SLURM_SUBMIT_DIR/scripts/slurm_runs/train_jobs.py" ]; then
  PROJECT_DIR="$SLURM_SUBMIT_DIR"
else
  SUBMIT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
  PROJECT_DIR="$(cd "$SUBMIT_DIR/../../.." && pwd)"
fi
cd "$PROJECT_DIR"

if [ ! -f "$PROJECT_DIR/scripts/slurm_runs/train_jobs.py" ]; then
  echo "ERROR: repository root not found at $PROJECT_DIR" >&2
  echo "Run sbatch from the repository root (see scripts/slurm_runs/README.md)." >&2
  exit 1
fi

set +u
if [ -f "${CONDA_EXE%/*}/../etc/profile.d/conda.sh" ]; then
  source "${CONDA_EXE%/*}/../etc/profile.d/conda.sh"
elif [ -f "$HOME/miniconda3/etc/profile.d/conda.sh" ]; then
  source "$HOME/miniconda3/etc/profile.d/conda.sh"
elif [ -f "$HOME/anaconda3/etc/profile.d/conda.sh" ]; then
  source "$HOME/anaconda3/etc/profile.d/conda.sh"
else
  echo "ERROR: conda.sh not found" >&2
  exit 1
fi
conda activate new_opt
set -u

JOBS_FILE="$PROJECT_DIR/scripts/slurm_runs/penalty_pf/jobs.jsonl"
TASK_ID="${SLURM_ARRAY_TASK_ID:?SLURM_ARRAY_TASK_ID not set}"

case "$TASK_ID" in
  6|7|8|9|10|11|21|22|23|24|25|26|36|37|38|39|40|41|51|52|53|54|55|56) ;;
  *)
    echo "ERROR: SLURM_ARRAY_TASK_ID=$TASK_ID is not allowed for $(basename "${BASH_SOURCE[0]}")" >&2
    echo "Allowed jobs.jsonl indices: 6 7 8 9 10 11 21 22 23 24 25 26 36 37 38 39 40 41 51 52 53 54 55 56" >&2
    echo "Regenerate with train_jobs.py generate and sbatch this script without --array overrides." >&2
    exit 1
    ;;
esac

python "$PROJECT_DIR/scripts/slurm_runs/train_jobs.py" run --jobs "$JOBS_FILE" --index "$TASK_ID" --expect-resource-profile medium

